package com.adsamcik.tracker.tracker.component.consumer.postimport android.content.Contextimport com.adsamcik.tracker.shared.base.Timeimport com.adsamcik.tracker.shared.base.data.ActivityInfoimport com.adsamcik.tracker.shared.base.data.CollectionDataimport com.adsamcik.tracker.shared.base.data.Locationimport com.adsamcik.tracker.shared.base.data.TrackerSessionimport com.adsamcik.tracker.shared.base.database.AppDatabaseimport com.adsamcik.tracker.shared.base.database.dao.FrequentPlaceDaoimport com.adsamcik.tracker.shared.base.database.dao.InferredTripDaoimport com.adsamcik.tracker.shared.base.database.dao.SessionSegmentDaoimport com.adsamcik.tracker.shared.base.database.dao.TripLegDaoimport com.adsamcik.tracker.shared.base.database.data.SegmentSourceimport com.adsamcik.tracker.shared.base.database.data.SessionSegmentimport com.adsamcik.tracker.stats.api.DetectedActivityTypeimport com.adsamcik.tracker.stats.api.PolicyEscalationEngineimport com.adsamcik.tracker.stats.api.PolicyTierimport com.adsamcik.tracker.tracker.component.producer.StepDataProducerimport com.adsamcik.tracker.tracker.data.collection.MutableCollectionTempDataimport io.kotest.matchers.shouldBeimport io.mockk.coEveryimport io.mockk.coVerifyimport io.mockk.everyimport io.mockk.mockkimport io.mockk.mockkObjectimport io.mockk.slotimport io.mockk.unmockkObjectimport io.mockk.verifyimport kotlinx.coroutines.test.runTestimport org.junit.jupiter.api.AfterEachimport org.junit.jupiter.api.BeforeEachimport org.junit.jupiter.api.Test/** * Test suite for [SessionSegmentWriter]. * * Verifies: * - Activity type mapping (Google Play Services int Ôåö DetectedActivityType) * - Segment source classification based on confidence and user-initiated flag * - GPS escalation engine integration on trip start/end/cancel * - Segment persistence with trip enrichment * - Edge cases: no location, disable with active trip */class SessionSegmentWriterTest {	private lateinit var writer: SessionSegmentWriter	private lateinit var context: Context	private lateinit var mockDatabase: AppDatabase	private lateinit var mockSegmentDao: SessionSegmentDao	private lateinit var mockInferredTripDao: InferredTripDao	private lateinit var mockTripLegDao: TripLegDao	private lateinit var mockFrequentPlaceDao: FrequentPlaceDao	private lateinit var mockEscalationEngine: PolicyEscalationEngine	@BeforeEach	fun setup() {		context = mockk(relaxed = true)		mockDatabase = mockk(relaxed = true)		mockSegmentDao = mockk(relaxed = true)		mockInferredTripDao = mockk(relaxed = true)		mockTripLegDao = mockk(relaxed = true)		mockFrequentPlaceDao = mockk(relaxed = true)		mockEscalationEngine = mockk(relaxed = true)		every { mockDatabase.sessionSegmentDao() } returns mockSegmentDao		every { mockDatabase.inferredTripDao() } returns mockInferredTripDao		every { mockDatabase.tripLegDao() } returns mockTripLegDao		every { mockDatabase.frequentPlaceDao() } returns mockFrequentPlaceDao		mockkObject(AppDatabase.Companion)		every { AppDatabase.database(any()) } returns mockDatabase		mockkObject(Time)		every { Time.nowMillis } returns BASE_TIME		coEvery { mockSegmentDao.insert(any<SessionSegment>()) } returns 1L		coEvery { mockInferredTripDao.insertAndGetId(any()) } returns 100L		coEvery { mockFrequentPlaceDao.getAll(any()) } returns emptyList()		writer = SessionSegmentWriter()	}	@AfterEach	fun teardown() {		unmockkObject(AppDatabase.Companion)		unmockkObject(Time)	}	private fun createCollectionData(		latitude: Double? = null,		longitude: Double? = null,		speed: Float? = null,		accuracy: Float? = 10f,		activityType: Int? = null,		activityConfidence: Int? = null,	): CollectionData {		val data = mockk<CollectionData>(relaxed = true)		if (latitude != null && longitude != null) {			val location = mockk<Location>()			every { location.latitude } returns latitude			every { location.longitude } returns longitude			every { location.speed } returns speed			every { location.horizontalAccuracy } returns accuracy			every { data.location } returns location		} else {			every { data.location } returns null		}		if (activityType != null && activityConfidence != null) {			val activity = mockk<ActivityInfo>()			every { activity.activityType } returns activityType			every { activity.confidence } returns activityConfidence			every { data.activity } returns activity		} else {			every { data.activity } returns null		}		return data	}	private fun createTempData(timeMs: Long, steps: Int? = null): MutableCollectionTempData {		val tempData = MutableCollectionTempData(timeMs, timeMs * 1_000_000)		if (steps != null) {			tempData.set(StepDataProducer.NEW_STEPS_ARG, steps)		}		return tempData	}	private fun createSession(): TrackerSession = mockk(relaxed = true)	// --- Activity Type Mapping ---	@Test	fun `mapActivityType maps IN_VEHICLE correctly`() {		SessionSegmentWriter.mapActivityType(0) shouldBe DetectedActivityType.IN_VEHICLE	}	@Test	fun `mapActivityType maps ON_BICYCLE correctly`() {		SessionSegmentWriter.mapActivityType(1) shouldBe DetectedActivityType.ON_BICYCLE	}	@Test	fun `mapActivityType maps ON_FOOT correctly`() {		SessionSegmentWriter.mapActivityType(2) shouldBe DetectedActivityType.ON_FOOT	}	@Test	fun `mapActivityType maps STILL correctly`() {		SessionSegmentWriter.mapActivityType(3) shouldBe DetectedActivityType.STILL	}	@Test	fun `mapActivityType maps TILTING correctly`() {		SessionSegmentWriter.mapActivityType(5) shouldBe DetectedActivityType.TILTING	}	@Test	fun `mapActivityType maps WALKING correctly`() {		SessionSegmentWriter.mapActivityType(7) shouldBe DetectedActivityType.WALKING	}	@Test	fun `mapActivityType maps RUNNING correctly`() {		SessionSegmentWriter.mapActivityType(8) shouldBe DetectedActivityType.RUNNING	}	@Test	fun `mapActivityType maps unknown values to UNKNOWN`() {		SessionSegmentWriter.mapActivityType(4) shouldBe DetectedActivityType.UNKNOWN		SessionSegmentWriter.mapActivityType(99) shouldBe DetectedActivityType.UNKNOWN		SessionSegmentWriter.mapActivityType(-1) shouldBe DetectedActivityType.UNKNOWN	}	// --- Activity Type Reverse Mapping ---	@Test	fun `mapActivityTypeToInt round-trips all known types`() {		DetectedActivityType.entries.forEach { type ->			val asInt = SessionSegmentWriter.mapActivityTypeToInt(type)			SessionSegmentWriter.mapActivityType(asInt) shouldBe type		}	}	@Test	fun `mapActivityTypeToInt maps UNKNOWN to 4`() {		SessionSegmentWriter.mapActivityTypeToInt(DetectedActivityType.UNKNOWN) shouldBe 4	}	// --- Escalation Engine Integration ---	@Test	fun `onEnable initializes without escalation engine`() = runTest {		writer.onEnable(context)		writer.onDisable(context)		// No crash - escalation engine is optional	}	@Test	fun `onDisable clears escalation engine minimum tier`() = runTest {		writer.setEscalationEngine(mockEscalationEngine)		writer.onEnable(context)		writer.onDisable(context)		verify { mockEscalationEngine.clearMinimumTier() }	}	// --- Data Flow Without Location ---	@Test	fun `onNewData without location does not crash`() = runTest {		writer.onEnable(context)		writer.onNewData(			context, createSession(),			createCollectionData(),			createTempData(BASE_TIME)		)		writer.onDisable(context)	}	@Test	fun `onNewData with location but no activity processes normally`() = runTest {		writer.onEnable(context)		writer.onNewData(			context, createSession(),			createCollectionData(latitude = 50.0, longitude = 14.0),			createTempData(BASE_TIME)		)		writer.onDisable(context)	}	// --- Segment Source Classification ---	@Test	fun `classifySource returns USER_CREATED when user initiated`() = runTest {		val capturedSegments = mutableListOf<SessionSegment>()		coEvery { mockSegmentDao.insert(capture(capturedSegments)) } returns 1L		writer.setUserInitiated(true)		writer.setEscalationEngine(mockEscalationEngine)		writer.onEnable(context)		// Feed enough data to trigger a trip via the detector		feedMovingSequence(startLat = 50.0, startLon = 14.0, count = 20, intervalMs = 10_000)		// Force disable to end any active trip		every { Time.nowMillis } returns BASE_TIME + 300_000L		writer.onDisable(context)		// Allow async persistence to complete		Thread.sleep(500)		// If a segment was persisted, verify it's USER_CREATED		if (capturedSegments.isNotEmpty()) {			capturedSegments.last().source shouldBe SegmentSource.USER_CREATED		}	}	// --- Enable/Disable Lifecycle ---	@Test	fun `enable then disable with no data does not persist segments`() = runTest {		writer.onEnable(context)		writer.onDisable(context)		coVerify(exactly = 0) { mockSegmentDao.insert(any<SessionSegment>()) }	}	@Test	fun `multiple enable-disable cycles reset state cleanly`() = runTest {		writer.setEscalationEngine(mockEscalationEngine)		writer.onEnable(context)		writer.onNewData(			context, createSession(),			createCollectionData(latitude = 50.0, longitude = 14.0),			createTempData(BASE_TIME)		)		writer.onDisable(context)		// Second cycle		writer.onEnable(context)		writer.onNewData(			context, createSession(),			createCollectionData(latitude = 51.0, longitude = 15.0),			createTempData(BASE_TIME + 500_000)		)		writer.onDisable(context)		// Should not crash or leak state between cycles	}	// --- Single Location Point ---	@Test	fun `single location point produces no distance delta`() = runTest {		writer.onEnable(context)		writer.onNewData(			context, createSession(),			createCollectionData(latitude = 50.0, longitude = 14.0, speed = 0f),			createTempData(BASE_TIME)		)		writer.onDisable(context)		// No trip should be detected from a single stationary point		coVerify(exactly = 0) { mockSegmentDao.insert(any<SessionSegment>()) }	}	// --- Stationary Data ---	@Test	fun `stationary location updates produce no trip`() = runTest {		writer.onEnable(context)		// Same location repeated		repeat(5) { i ->			writer.onNewData(				context, createSession(),				createCollectionData(					latitude = 50.0,					longitude = 14.0,					speed = 0f,					activityType = 3, // STILL					activityConfidence = 90,				),				createTempData(BASE_TIME + i * 5_000L)			)		}		writer.onDisable(context)		coVerify(exactly = 0) { mockSegmentDao.insert(any<SessionSegment>()) }	}	// --- SetUserInitiated flag ---	@Test	fun `setUserInitiated false does not mark segments as USER_CREATED`() = runTest {		writer.setUserInitiated(false)		writer.onEnable(context)		writer.onDisable(context)		// No segments to verify, but the flag is set correctly for future segments	}	// --- Escalation Engine on forceEnd ---	@Test	fun `forceEnd on disable clears escalation engine`() = runTest {		writer.setEscalationEngine(mockEscalationEngine)		writer.onEnable(context)		// Feed location data to initialize state		writer.onNewData(			context, createSession(),			createCollectionData(latitude = 50.0, longitude = 14.0, speed = 5f),			createTempData(BASE_TIME)		)		every { Time.nowMillis } returns BASE_TIME + 60_000		writer.onDisable(context)		verify { mockEscalationEngine.clearMinimumTier() }	}	// --- Helper ---	private fun feedMovingSequence(		startLat: Double,		startLon: Double,		count: Int,		intervalMs: Long,	) {		repeat(count) { i ->			val lat = startLat + (i * 0.001) // ~111m per step			val timeMs = BASE_TIME + (i * intervalMs)			every { Time.nowMillis } returns timeMs			writer.onNewData(				context, createSession(),				createCollectionData(					latitude = lat,					longitude = startLon,					speed = 5f,					activityType = 7, // WALKING					activityConfidence = 80,				),				createTempData(timeMs, steps = 100)			)		}	}	companion object {		private const val BASE_TIME = 1_700_000_000_000L	}}